Corollary 1.13 — the requested cited result (source label coro:bona fide lip ext)
\begin{corollary}\label{coro:bona fide lip ext}
Under the assumptions of Theorem~\ref{thm:general keith}, if in
addition $Y$ is a dual Banach space  then $e(X,Y)\lesssim
M_p(X)N_p(Y)$. If $p=2$ and $Y$ is a complete $CAT(0)$ metric space then
$e(X,Y)\lesssim M_2(X)$.
\end{corollary}

Theorem 1.11 — hypotheses referenced by Corollary 1.13; equation (8)
\begin{theorem}[generalized Ball extension theorem]\label{thm:general keith}
Fix $p,\Gamma\in [1,\infty)$. Let $(X,d_X)$ be a metric space of Markov type $p$ and let $(Y,d_Y)$ be a metric space of metric Markov cotype $p$ that is $W_p$ barycentric with constant $\Gamma$. Suppose that $Z\subseteq X$ and $f:Z\to Y$ is Lipschitz. Then for every finite subset $S\subseteq X$ there exists $F:S\to Y$ with $F|_{S\cap Z}=f|_{S\cap Z}$ and
\begin{equation}\label{eq:extension lip bound}
\|F\|_{\Lip} \lesssim \Gamma M_p(X)N_p(Y)\|f\|_{\Lip}.
\end{equation}
\end{theorem}

Definition of the Lipschitz extension modulus used by Corollary 1.13
If $(X,d_X)$ and $(Y,d_Y)$ are metric spaces then for every
$S\subseteq X$ denote by $e(X,S,Y)$ the infimum over those $L\in
(0,\infty)$ such that for {\em every} Lipschitz function $f:S\to Y$
there exists $F:X\to Y$ with $F(x)=f(x)$ for every $x\in S$ such that $\|F\|_{\Lip}\le L\|f\|_{\Lip}$,
where $\|f\|_{\Lip}$ denotes the Lipschitz constant of $f$. If no
such $L$ exists then set $e(X,S,Y)=\infty$.

Defining
$$
e(X,Y)\eqdef \sup\left\{e(X,S,Y):\ S\subseteq X\right\},
$$


Definition 1.1 — Markov type; equation (1)
\begin{definition}[Markov type $p$]\label{def:Mtype}
A metric space $(X,d_X)$ is a said to have Markov type $p\in (0,\infty)$ with constant $M\in (0,\infty)$ if  for every $n,t\in
\N$ and every $\pi\in \Delta^{n-1}$, if $A=(a_{ij})\in M_n(\R)$ is  a stochastic matrix that is reversible relative to $\pi$ then every $x_1,\ldots,x_n\in X$ satisfy
\begin{equation}\label{eq:to reverse type}
\sum_{i=1}^n\sum_{j=1}^n \pi_i(A^t)_{ij}d_X(x_i,x_j)^p\le M^pt\sum_{i=1}^n\sum_{j=1}^n \pi_ia_{ij}d_X(x_i,x_j)^p.
\end{equation}
The infimum over those $M\in (0,\infty)$ satisfying~\eqref{eq:to reverse type} is denoted $M_p(X)$.
\end{definition}

Definition 1.2 — metric Markov cotype; equation (2) (including the original source reference as printed)
\begin{definition}[metric Markov cotype $p$]\label{def:Mcotype} A metric space $(X,d_X)$ is said to have metric Markov cotype $p\in (0,\infty)$ with constant $N\in (0,\infty)$ if  for every $n,t\in
\N$ and every $\pi\in \Delta^{n-1}$, if $A=(a_{ij})\in M_n(\R)$ is  a stochastic matrix that is reversible relative to $\pi$ then for every $x_1,\ldots,x_n\in X$ there exist $y_1,\ldots,y_n\in X$
satisfying
\begin{multline}\label{def:markov cotype}
\sum_{i=1}^n \pi_id_X(x_i,y_i)^p+t\sum_{i=1}^n\sum_{j=1}^n \pi_ia_{ij}
d_X(y_i,y_j)^p\\\le N^p\sum_{i=1}^n\sum_{j=1}^n
\pi_i\left(\frac{1}{t}\sum_{s=1}^{t}A^s\right)_{ij}d_X(x_i,x_j)^p.
\end{multline}
The infimum over those $N\in (0,\infty)$ satisfying~\eqref{eq:to
reverse type} is denoted $N_p(X)$.
%$(X,d_X)$ is said to have metric Markov cotype $p$ if $N_p(X)<\infty$.
\end{definition}

Definition 1.3 — barycentric hypothesis; equation (3)
\begin{definition}[$W_p$ barycentric metric space]\label{def:Wp}
Fix $p,\Gamma\in [1,\infty)$. A metric space $(X,d_X)$ is said to be $W_p$ barycentric with constant $\Gamma$ if there exists a mapping $\B:\P_X\to X$ satisfying $\B(\d_x)=x$ for every $x\in X$, and
\begin{equation}\label{eq:Gamma Wp Lip}
\forall\, \mu,\nu\in \P_X,\qquad d_X(\B(\mu),\B(\nu))\le \Gamma W_p(\mu,\nu).
\end{equation}
$(X,d_X)$ is said to be $W_p$ barycentric if it is $W_p$ barycentric with constant $\Gamma$ for some $\Gamma\in [1,\infty)$.
\end{definition}

Normed-space barycenter fact following Definition 1.3
Normed spaces are $W_1$ barycentric with constant $\Gamma=1$, as exhibited by the barycenter map $\B(\mu)=\int_X xd\mu(x)$.

